include <robotics.scad>
$fn = 48;
// --- official (Benewake TF-Luna manual Fig.3 / datasheet A05) ---
W      = 26.5;   // body width
D      = 12;     // body depth (without lens boss)
H      = 21.25;  // front-face height
boss   = 1.5;    // 13.5 overall - 12 body
lens_d = 10.5;   // lens diameter
lens_dx= 10.5/2; // lens centres 10.5 apart
lens_z = H - 9;  // lens centres 9 below top edge
blk_w  = 18;     // bottom connector block width
ear_t  = 2;      // ear thickness
ear_r  = 2.25;   // ear end radius
hole_d = 2.2;    // mounting hole
hole_dx= 30.5/2; // hole spacing 30.5
pcb_h  = 19;     // rear PCB height
con_reach = 6.8; // connector reaches 6.8 from back face
// --- not dimensioned (plain, conservative) ---
yb     = 13.5/2;     // back face
yf     = yb - D;     // front face of body
blk_h  = (H - pcb_h)/2;  // narrow block height (keeps 19 PCB inside full-width body)
r_c    = 1.5;        // corner radius
pcb_w  = 23.4;       // rear PCB pocket width (scaled from drawing)
seat_h = 1.0;        // lens seat depth into boss
pcb_t  = 1.0;        // PCB thickness
// connector cavity: from PCB front face to 0.2 beyond the 6.8 reach
con_y1 = yb - pcb_t;            // 5.75
con_y0 = yb - con_reach - 0.2;  // -0.25
con    = [10.5, con_y1 - con_y0, 4.0];

module ear(s) translate([0, yb, lens_z]) xrot(90) linear_extrude(ear_t)
  hull() { translate([s*hole_dx, 0]) circle(r = ear_r);
           translate([s*(W/2 - 1.5), 0]) square([3, 2*ear_r + 3], center = true); }

difference() {
  union() {
    // main body
    translate([0, (yb + yf)/2, blk_h]) cuboid([W, D, H - blk_h], rounding = r_c, edges = "Y", anchor = BOT);
    // narrow bottom block (18 wide)
    translate([0, (yb + yf)/2, 0]) cuboid([blk_w, D, blk_h + 1], rounding = 0.5, edges = "Y", except = TOP, anchor = BOT);
    // lens boss: stadium around both lenses, 1.5 proud
    translate([0, yf + 0.01, lens_z]) xrot(90) linear_extrude(boss + 0.01)
      hull() for (s = [-1, 1]) translate([s*lens_dx, 0]) circle(d = lens_d);
    // mounting ears
    for (s = [-1, 1]) ear(s);
  }
  // Ø2.2 through holes
  for (s = [-1, 1]) translate([s*hole_dx, yb, lens_z]) ycyl(d = hole_d, h = 10);
  // Ø10.5 lens seats
  for (s = [-1, 1]) translate([s*lens_dx, yf - boss - 0.01, lens_z]) xrot(-90) cyl(d = lens_d, h = seat_h + 0.01, anchor = BOT);
  // rear PCB pocket
  translate([0, yb + 0.01, H/2]) cuboid([pcb_w, pcb_t + 0.01, pcb_h + 0.4], rounding = 1, edges = "Y", anchor = BACK);
  // bottom connector cavity
  translate([0, (con_y0 + con_y1)/2, -0.01]) cuboid([con.x, con.y, con.z + 0.01], anchor = BOT);
}

include <robotics.scad>
$fn = 32;
// 19 mm tall (manual Fig.3 rear view); 23 x 1.0 not dimensioned
translate([0, 13.5/2, 21.25/2]) cuboid([23, 1.0, 19], rounding = 0.8, edges = "Y", anchor = BACK);

include <robotics.scad>
// y from back face 6.75: PCB front (5.75) to 6.8 reach (-0.05); top touches cavity ceiling z = 4.0
y0 = 13.5/2 - 6.8;  y1 = 13.5/2 - 1.0;  yc = (y0 + y1)/2;
difference() {
  translate([0, yc, 4.0]) cuboid([10.1, y1 - y0, 3.6], anchor = TOP);
  translate([0, yc, 0.39]) cuboid([8.6, 2.4, 2.6], anchor = BOT);   // plug opening (faces down)
}

